"""Cuaderno del estudiante, 3.º medio Lengua y Literatura FG, OAC 06 (producción coherente y cohesionada según género y audiencia).

Todos los textos, fichas y casos son originales e inventados («de ejemplo»); cada ejercicio trae escritos los datos que necesita.
Los títulos de las clases del repositorio ordenan el proceso de escritura; este cuaderno los sigue.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from fg_leli_common import L, E, arith  # noqa: E402,F401

OA = "FG-LELI-3M-OAC-06"


def AB(q, right, wrong, why):
    """Pregunta de dos alternativas; la correcta se escribe primero y el registro la reubica."""
    return E(f"{q} A) {right} B) {wrong}", f"A) {right}", why)


