  [("propósito", "lo que quien escribe quiere lograr con su texto"), ("audiencia", "las personas que leerán, escucharán o verán el texto"), ("género discursivo", "forma de texto con rasgos propios, como la reseña o el discurso"), ("situación comunicativa", "conjunto de quién habla, a quién, sobre qué, para qué y por qué medio")],
